  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '2f8359db-221e-4a64-b2df-2b3e7b74a2db', 'Expresando muestras de afecto sinceras y cuidadosas a las integrantes de mi patrulla.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '3621f4ae-1316-4b3e-8682-3e3c9ad381a7', 'Disfrutando el reconocimiento y las palabras estimulantes brindadas por mis compañeras.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '3a35ddd8-f6dc-4e00-a04d-107a0825bd99', 'Fortaleciendo mi sentido de pertenencia y valoración propia ante la patrulla de guías.') ON CONFLICT DO NOTHING;
