  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb', 'Recibiendo con gratitud la acogida positiva de mis compañeros al recorrer la fila.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '62876ebe-214f-4caf-b164-664e12fd30ae', 'Afirmando mi autoestima y confianza personal al integrarme en la fila del grupo.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '6c2b5054-70e8-4529-957f-a8abea073918', 'Manifestando mis sentimientos y empatía abiertamente para fortalecer el clima de confianza de la comunidad.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '6e25f6ed-277c-41b4-9d0f-322b0a2d4c94', 'Ofreciendo palmaditas y gestos de cariño respetuoso a mis compañeros de seisena al pasar por el túnel del lavado.') ON CONFLICT DO NOTHING;
