  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'a4060c60-7ce9-425b-bf2a-76941a689937', 'Brindando contacto físico fraterno y respetuoso a cada participante de la patrulla.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'b66418eb-3eee-466e-9836-457b3bb922cc', 'Sintiéndome seguro y querido por la seisena durante la evaluación y cierre de la dinámica.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'beb4b3e4-fe1c-4f06-af34-2c7f88202eb7', 'Aportando calidez y empatía para desinhibir y motivar a las compañeras.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'c380e11a-571d-4617-924c-aa933ae30138', 'Aceptando con madurez y alegría las expresiones de aprecio de los demás participantes.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'c8993915-0234-464c-934e-2a09f8c4338e', 'Participando con alegría y sin vergüenza al brindar y recibir las demostraciones de afecto del grupo.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'd252cb51-c224-4528-90b3-e0288aa343dd', 'Generando un clima de distensión y encuentro auténtico al inicio de las sesiones de la comunidad.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'd581cfa7-db1f-4b08-b4d3-525b23e418ea', 'Fomentando un canal de comunicación afectuoso entre las integrantes de la patrulla.') ON CONFLICT DO NOTHING;
